import os

def expected_output(grid):
    h, w = len(grid), len(grid[0])

    # Find the row with 2s (only one such row expected)
    basis_row = None
    for r in range(h):
        if any(grid[r][c] == 2 for c in range(w)):
            basis_row = r
            break

    # Find dust 4s
    dust_4s = []
    for r in range(h):
        if r != basis_row:
            for c in range(w):
                if grid[r][c] == 4:
                    dust_4s.append((r, c))

    result = [[0]*w for _ in range(h)]

    for r0, c0 in dust_4s:
        # Distance to the 2-basis row
        distance = abs(r0 - basis_row)

        # Primary dust: diagonal band at distance = dist, and orthogonal at dist
        for r in range(max(0, r0 - distance), min(h, r0 + distance + 1)):
            for c in range(max(0, c0 - distance), min(w, c0 + distance + 1)):
                # Check if (r,c) is on the diagonal/orthogonal band
                if abs(r - r0) == abs(c - c0) and abs(r - r0) <= distance:
                    result[r][c] = 4

        # Secondary dust: unit distance band
        for r in range(max(0, r0 - distance), min(h, r0 + distance + 1)):
            for c in range(max(0, c0 - distance), min(w, c0 + distance + 1)):
                # Check if (r,c) is within unit distance band
                if (abs(r - r0) == 1 or abs(c - c0) == 1) and abs(r - r0) <= distance and abs(c - c0) <= distance:
                    result[r][c] = 4

    return result

