def transform_debug(grid, debug=True):
    """Debug version with detailed output"""
    h, w = len(grid), len(grid[0])

    basis_row = None
    for r in range(h):
        if any(grid[r][c] == 2 for c in range(w)):
            basis_row = r
            break

    dust_4s = []
    for r in range(h):
        if r != basis_row:
            for c in range(w):
                if grid[r][c] == 4:
                    dust_4s.append((r, c))

    # Use a clean result, not copying original grid
    result = [[0] * w for _ in range(h)]

    for r0, c0 in dust_4s:
        surface_distance = abs(r0 - basis_row)

        # Pattern range
        row_start = r0 - 1
        row_end = r0 + surface_distance - 1

        for r in range(max(0, row_start), min(h - 1, row_end)):
            col_dist = r0 + 1 - r
            if col_dist < 0:
                continue
            row_str = f"  r={r}: |c-{c0}|={col_dist}"
            if debug:
                print(f"Processing 4 at ({r0},{c0}): surface={surface_distance}, pattern rows [{row_start},{row_end}]")
                print(row_str)
            for dc in [-col_dist, col_dist]:
                if dc == 0:
                    c = c0
                else:
                    c1, c2 = c0 + dc, c0 - dc
                    # Check if both are equal (shouldn't be)
                    if c1 == c2 and dc != 0:
                        c1, c2 = c1, c2  # They should be different
                    if dc == 0:
                        c = c1  # Only one column
                if 0 <= c < w:
                    result[r][c] = 4

            if debug:
                print(f"  After r={r}: {[result[r][c] for c in range(w)]}")

        if debug:
            print(f"Completed 4 at ({r0},{c0}). Row state:")
            for row in result:
                print(row)
        print()

    return result

