def transform_trace(grid, trace=True):
    if not grid or not grid[0]:
        return grid[:]

    h, w = len(grid), len(grid[0])

    basis_row = None
    for r in range(h):
        if any(grid[r][c] == 2 for c in range(w)):
            basis_row = r
            break

    if basis_row is None:
        return grid[:]

    dust_4s = []
    for r in range(h):
        if r != basis_row:
            for c in range(w):
                if grid[r][c] == 4:
                    dust_4s.append((r, c))

    result = [[0] * w for _ in range(h)]

    for r0, c0 in dust_4s:
        surface_distance = abs(r0 - basis_row)
        row_start = r0 - 1
        row_end = r0 + surface_distance - 1

        if trace:
            print(f"\nProcessing dust 4 at ({r0},{c0}):")
            print(f"  surface_distance = {surface_distance}")
            print(f"  row_start = {row_start}, row_end = {row_end}")
            print(f"  range: [{max(0, row_start)} to min({h-1}, {row_end}) = min({h-1}, {row_end}) = {min(h-1, row_end)}]")

        for r in range(max(0, row_start), min(h - 1, row_end)):
            col_dist = r0 + 1 - r

            if trace:
                print(f"  r={r}: col_dist = {r0} + 1 - {r} = {col_dist}")

            if col_dist < 0:
                print(f"  col_dist < 0, skipping")
                continue

            if trace:
                print(f"  Col range: {c0 - col_dist} to {c0 + col_dist}")

            if col_dist == 0:
                c = c0
                if 0 <= c < w:
                    result[r][c] = 4
                    if trace:
                        print(f"  Placed 4 at ({r}, {c})")
            else:
                c1 = c0 - col_dist
                c2 = c0 + col_dist
                if trace:
                    print(f"  Columns: c1={c1}, c2={c2}")
                if 0 <= c1 < w:
                    result[r][c1] = 4
                    if trace:
                        print(f"  Placed 4 at ({r}, {c1})")
                if 0 <= c2 < w:
                    result[r][c2] = 4
                    if trace:
                        print(f"  Placed 4 at ({r}, {c2})")

        if trace:
            print(f"  State after this dust 4:")
            for row_idx, row in enumerate(result):
                if any(row):
                    print(f"    row {row_idx}: {row}")

    return result

